/// <summary>
/// MPJ_2677 - Kscerri - 10/06/2021
/// The <t>ReasonTableRef</t> table extension
/// </summary>
[ExtensionOf(tablestr(ReasonTableRef))]
final class METReasonTableRef_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_2677 - Kscerri - 10/06/2021
    /// </summary>
    /// <param name = "_reasonCode"> reason code </param>
    /// <returns>reasonTableRef</returns>
    public static ReasonTableRef findByReasonCode(ReasonCode _reasonCode)
    {
        ReasonTableRef reasonTableRef;

        select firstonly reasonTableRef
            where reasonTableRef.Reason == _reasonCode;

        return reasonTableRef;
    }
